    "hillshade-highlight-color": "rgba(240,236,222,0.04)",
    "hillshade-shadow-color": "rgba(12,18,10,0.55)",
    "hillshade-accent-color": "rgba(12,18,10,0)",
    "hillshade-exaggeration": 0.6,
