      "circle-radius": mapOutputs(p["circle-radius"] === undefined ? 5 : p["circle-radius"], (n) => n * 1.5),
      "circle-blur": 1, "circle-opacity": z(GLOW.fadeOut, 0, GLOW.gone, 0.2),
