  for (const k of ["type", "commodity", "company", "country"]) if (o[k] != null) o[k] = ejWords(o[k]);
  for (const k of ["status", "project_status", "reaction"]) if (o[k] != null) { o[`${k.replace("_", " ")} (EJAtlas's own code number)`] = o[k]; delete o[k]; }
