// Headings whose lists ran long are split one level further (item 27, round
// 23). A row filed under one of these headings goes into the first
// sub-heading whose rule its words match; the last rule of each catches the
// rest, so no row is left between a heading and its sub-headings. Filed by
// what a row shows, never by who published it.
const CATALOGUE_SUBS = {
  [P + " > Deforestation"]: [
    [/greenhouse|emission|net flux|removals?\b/i, "Emissions from forests"],
    [/concession|permit|\bpbph\b|\bfca\b|management objective|logging|timber concession/i, "Logging and timber concessions"],
    [/rubber|plantation/i, "Timber and rubber plantations"],
    [/.*/, "Logging and timber concessions"],
  ],
  [P + " > Deforestation > Tree cover loss and alerts"]: [
    // Round 88b (asked 27 September): the emissions of clearing for one product
    // go under that product; only those of all clearing stay under Emissions.
    [/(?=.*emission)(?=.*(cattle|pasture|beef))/i, "Cattle"],
    [/(?=.*emission)(?=.*(\bsoy|\bcorn\b))/i, "Soy and corn"],
    [/(?=.*emission)(?=.*cocoa)/i, "Cocoa"],
    [/(?=.*emission)(?=.*palm)/i, "Palm oil"],
    [/(?=.*emission)(?=.*pulp)/i, "Wood pulp"],
    [/emission/i, "Emissions from the clearing"],
    [/driver|agriculture.linked/i, "What drove the loss"],
    [/alert|trees cut|dist-?alert|\bglad\b|\bradd\b/i, "Alerts"],
    [/expansion/i, "Plantations spreading"],
    [/probability|risk|frontera/i, "Where clearing is likely"],
    // Round 88b: each product heading is the product's name alone.
    [/cattle|pasture|beef/i, "Cattle"],
    [/\bsoy|\bcorn\b/i, "Soy and corn"],
    [/cocoa/i, "Cocoa"],
    [/palm/i, "Palm oil"],
    [/pulp|concession/i, "Wood pulp"],
    [/.*/, "Loss year by year"],
  ],
  [P + " > Biodiversity loss"]: [
    [/dist-?alert|disturb/i, "Disturbance"],
    // Round 90b (asked 27 September): the terrestrial ecoregions with the land cover.
    [/ecoregion|ecozone|land cover|land use/i, "Land Use and Ecoregions"],
    // Round 99b: Places that matter most for species in five parts.
    [/protect|conserv|reserve|easement|leuser|wdpa/i, "Places that matter most for species > Protected areas"],
    [/intact|primary forest|integrity|wild/i, "Places that matter most for species > Wild and intact places"],
    [/richness|richest/i, "Places that matter most for species > Species richness"],
    [/migrat/i, "Places that matter most for species > Where animals gather and migrate"],
    [/.*/, "Places that matter most for species > Where species are threatened"],
  ],
  [AG]: [
    [/pasture|grassland/i, "Pasture and grassland"],
    [/\bwater\b/i, "Water for crops"],
    [/deforest/i, "Clearing for farming"],
    // Round 101b: a plantation of one crop under that crop.
    [/coconut/i, "By crop > Coconut"],
    [/\bsago\b/i, "By crop > Sago"],
    [/.*/, PLANT_T],
  ],
  [CROPS + " > Palm oil"]: [
    [/\bmills?\b|refiner/i, "Mills and refineries"],
    [/deforest|emission/i, "Clearing and emissions, Indonesia"],
    [/concession/i, "Concessions"],
    [/.*/, "Plantations"],
  ],
  // Round 75: each gas split into Emissions, Culprits, Infrastructure and
  // Priority emitters. Catalogue rows are measures of emissions and of the
  // crops behind them, so they go under Emissions, bar storage and the oil and
  // gas concessions and wells, which are infrastructure.
  [P + " > Climate > Carbon dioxide"]: [
    [/.*/, "Emissions"],
  ],
  [P + " > Climate > Methane"]: [
    // Round 120b: wells and concessions under Culprits (the Infrastructure heading is gone).
    [/oil and gas|oil & gas|(?<!greenhouse )\bgas\b|petroleum|geothermal|concession|\bwells?\b/i, "Culprits"],
    [/.*/, "Emissions"],
  ],
  [P + " > Climate > Nitrous oxide"]: [
    // Round 120b: storage is no longer a heading under Nitrous oxide.
    [/silo|storage|warehouse/i, null],
    [/.*/, "Emissions"],
  ],
  [P + " > Meat and agriculture > Meat"]: [
    // Round 95b: counts of animals (Paraguay's cattle herd size) under Herds.
    [/\bherds?\b|herd size|head count|\bheads? of cattle\b|number of (cattle|animals)/i, "Herds"],
    // Round 132b: Pigs and chickens and Cattle and pasture are gone.
    [/.*/, null],
  ],
};
function catalogueSub(path, words) {
  const rules = CATALOGUE_SUBS[path];
  if (!rules) return path;
  for (const [rule, sub] of rules) if (rule.test(words)) return sub ? `${path} > ${sub}` : path;
  return path;
}
// Rows whose words say peat are not land cover rows, whatever their group says
// (Trase files its peatland area under "Land cover"; item 26).
function catalogueRefine(paths, words) {
  let out = paths.filter((x) => !((x === P + " > Forest and land cover" || x === P + " > Biodiversity loss > Land Use and Ecoregions") && /\bpeat/i.test(words)));
  if (!out.length && paths.length) out = [P + " > Biodiversity loss > Land Use and Ecoregions > Peatland"];
  // Under Intact and primary forests only two rows stay (24 September): the
  // biodiversity intactness of forested biomes and the forest landscape
  // integrity index, both worldwide.
  // Boundaries and relief keeps only the GLAD-L coverage (24 September, round
  // 44): Nusantara's boundaries, imagery, relief, towns, photographs and news,
  // and Global Forest Watch's GADM and test boundaries are taken out.
  // The GLAD-L coverage row is taken out wherever it was filed (25 September).
  if (/coverage layer for glad-l|umd_glad_landsat_alerts_coverage/i.test(words)) return [CATALOGUE_TAKEN_OUT];
  const BR = "Base and reference > Boundaries and relief";
  // The GLAD-L coverage, the last row there, went on 25 September.
  if (out.includes(BR)) {
    out = out.filter((x) => x !== BR);
    if (!out.length) return [CATALOGUE_TAKEN_OUT];
  }
  // Round 95b (asked 27 September): the Intact Forest Landscapes are back, every year.
  const keepIntact = /intactness|integrity index|forest_landscape_integrity|intact forest landscape|ifl_intact/i.test(words);
  const subbed = out.map((x) => catalogueSub(x, words));
  if (!keepIntact && subbed.includes(P + " > Biodiversity loss > Intact and primary forests")) {
    out = out.filter((x, i) => subbed[i] !== P + " > Biodiversity loss > Intact and primary forests");
    if (!out.length) return [CATALOGUE_TAKEN_OUT];
  }
  // Round 99b: the heading is now Wild and intact places; the primary forest
  // rows taken out on 24 September stay out of it.
  if (!keepIntact && /primary forest/i.test(words) && subbed.includes(BIO_WILD)) {
    out = out.filter((x, i) => subbed[i] !== BIO_WILD);
    if (!out.length) return [CATALOGUE_TAKEN_OUT];
  }
  // Plantation rows for Indonesia and its neighbours are one row with
  // sublayers, detail beside the worldwide planted-trees row (24 September).
  // Emissions from forests are Climate's, not Deforestation's (24 September).
  out = out.map((x) => (catalogueSub(x, words) === P + " > Deforestation > Emissions from forests" ? P + " > Climate > Carbon dioxide" : x));
  const idn = /indonesia|papua|kalimantan|merauke|borneo|sumatra|sulawesi|\bjava\b|\bbali\b|equatorial asia|rawa singkil|\briau\b|\baceh\b|\bidn_?/i;
  return [...new Set(out.map((x) => catalogueSub(x, words)).map((x) => (x === PLANTS && idn.test(words) ? IN(PLANTS, "idnplant") : x)))];
}
// Where a catalogue layer is, said in its title. Nusantara names the place in
// most of its ids and covers Equatorial Asia in the rest; a reader clicking
// "Fire alerts, VIIRS" under Fire should not have to find out by drawing it
// that it stops at Indonesia. Read from the id, never assumed: a layer whose id
// says nothing takes the atlas's own stated coverage.
const NUSANTARA_WHERE = [
  [/^Global_|^v3p\d_Global/i, "worldwide"],
  [/BRNIDNMYS|BRNMYSIDN/i, "Brunei, Indonesia and Malaysia"],
  [/IDNMYSBorneo/i, "Borneo"],
  [/REGIDNMYS/i, "Indonesia and Malaysia"],
  [/^BALI_|badung|tabanan/i, "Bali"],
  [/^concessionfca_/i, "Papua New Guinea"],
  [/papua/i, "Papua"],
  [/merauke/i, "Merauke"],
  [/rawasingkil/i, "Rawa Singkil"],
  [/kalimantan/i, "Kalimantan"],
  [/^IDN_|_KLHK|^IDN/i, "Indonesia"],
];
// Round 83b (asked 27 September): the rubber plantation rows are not worldwide
// (the map covers the countries it covers, which its record does not list), so
// "worldwide" and "global" are taken out of their titles.
// Round 95b: the plantation layers of every kind, and the plantation expansion
// maps, are not worldwide either.
function notWorldwide(t) {
  if (!/rubber|plantation|planted|expansion|smallholder/i.test(t)) return t;
  return String(t).replace(/\s*\u2014\s*(worldwide|global[^\u2014]*)$/i, "").replace(/,?\s*\bworldwide\b/ig, "").replace(/\bglobal\s+/ig, "").trim();
}
// Round 101b: the area each place-name covers, so the map asks the server only
// for pictures over it (fewer pictures from a slow server, none over the
// rest of the world). Generous edges; worldwide layers are not bounded.
const NUSANTARA_BOUNDS = {
  "Brunei, Indonesia and Malaysia": [94, -12, 142, 8], "Borneo": [107.5, -4.8, 119.8, 7.6], "Indonesia and Malaysia": [94, -12, 142, 8],
  "Bali": [114.2, -9, 115.9, -7.9], "Papua New Guinea": [140.5, -12.5, 156.5, -0.5], "Papua": [128.5, -10, 141.5, 1],
  "Merauke": [137.5, -9.5, 141.5, -6], "Rawa Singkil": [97, 1.8, 98.5, 3.2], "Kalimantan": [107.5, -4.8, 119.5, 4.8],
  "Indonesia": [94, -12, 142, 7], "Equatorial Asia": [90, -13, 157, 22],
};
function nusantaraBounds(id) { return NUSANTARA_BOUNDS[nusantaraWhere(id)] || null; }
function nusantaraWhere(id) {
  for (const [rule, where] of NUSANTARA_WHERE) if (rule.test(id)) return where;
  return "Equatorial Asia";
}

