function siteLink(id) {
  const u = LAYER_SITE[id];
  if (!u) return "";
  let host = u;
  try { host = new URL(u).hostname.replace(/^www\./, ""); } catch (e) { /* shown whole */ }
  return `<a class="src" href="${escapeHtml(u)}" target="_blank" rel="noopener" ` +
    `title="Open ${escapeHtml(host)}" aria-label="Open ${escapeHtml(host)}, the source of this layer">\u2197</a>`;
}

// Which rows read their source as you look at them, rather than a copy kept
// here. A reader cannot tell by looking, and the difference matters: a live row
// shows what the source says right now and goes dark when the source does; a
// copy is as old as its last build. Archives, sitemaps, shapes and country
// shadings are copies and carry no mark.
const LIVE_ROUTES = new Set([
  "worker", "tile", "wmts", "rasterlive", "cerulean", "coral", "carbonmapper",
  "arcgis", "arcgisdyn", "arcgisapp", "umap", "kml", "ll2", "ejatlas", "geojsonlive",
  "wpgmza", "atlascities", "trase", "trasefac", "wmsmenu", "gfwmenu", "giga", "gta",
  "rte", "owidgrapher", "spheres", "companion", "gsn", "leave", "adsbmil", "gdeltgeo", "pmvector",
  // The Unearthings map's own files, read each time a row is ticked (round 77).
  "remains", "remainsfac", "remainsfind", "remainspanel",
  // The biosignature worlds are read from the assessment page itself each time.
  "worldsring",
  // Round 82b: the nitrogen dioxide relief, read from Global Forest Watch's tiles.
  "no2relief",
]);
// A row's longer description sits behind a small "i" beside its other marks.
// It used to be the whole row's hover text, which popped up over the list every
// time the pointer crossed it; an ordinary row's note was shown nowhere at all.
function infoMark(text) {
  // Paragraphs are kept (round 112b: the Eyes network's framing is several).
  const t = String(text || "").replace(/[ \t]+/g, " ").replace(/\n{3,}/g, "\n\n").trim();
  if (!t) return "";
  // A note that only says which page's map a layer came from tells the reader
  // nothing the row does not (round 62): no bubble for it.
  if (/^From (the |local-map)[^.]*\.$/.test(t) || /^From the Suppression page's network map/.test(t)) return "";
  return `<span class="info" tabindex="0" role="note" aria-label="About this layer" data-tip="${escapeHtml(t)}">i</span>`;
}
function wireInfoMarks() {
  const box = document.getElementById("layers");
  if (!box || !box.addEventListener || box.dataset.infoWired) return;
  box.dataset.infoWired = "1";
  const tip = document.createElement("div");
  tip.id = "row-tip";
  tip.hidden = true;
  document.body.appendChild(tip);
  const show = (el) => {
    tip.textContent = el.dataset.tip;
    tip.hidden = false;
    const r = el.getBoundingClientRect(), w = Math.min(340, window.innerWidth - 24);
    tip.style.width = w + "px";
    tip.style.left = Math.max(12, Math.min(r.left, window.innerWidth - w - 12)) + "px";
    const below = r.bottom + 8, h = tip.getBoundingClientRect().height;
    tip.style.top = (below + h > window.innerHeight - 8 ? Math.max(8, r.top - h - 8) : below) + "px";
  };
  const over = (e) => { const el = e.target && e.target.closest ? e.target.closest(".info") : null; if (el) show(el); };
  const out = (e) => { if (e.target && e.target.closest && e.target.closest(".info")) tip.hidden = true; };
  box.addEventListener("mouseover", over);
  box.addEventListener("focusin", over);
  box.addEventListener("mouseout", out);
  box.addEventListener("focusout", out);
  // The mark sits inside the row's label: a click on it must not tick the row.
  box.addEventListener("click", (e) => { if (e.target && e.target.closest && e.target.closest(".info")) e.preventDefault(); });
}

function liveMark(cfg) {
  if (!cfg) return "";
  const copy = NOT_LIVE[cfg.id];
  if (LIVE_ROUTES.has(cfg.route) && !copy) return `<span class="live" title="Read from the source itself when this row is ticked, not from a copy kept here">LIVE</span>` + refreshNote(cfg);
  const why = copy || "Drawn from a copy or file kept here, made when the source was last gathered, not read from the source each time";
  return `<span class="live notlive" title="${escapeHtml(why)}">NOT LIVE</span>` + refreshNote(cfg);
}
// How often what the row shows is renewed, as a small note beside its mark
// (asked for 23 September). A live row is read afresh each time it is ticked
// (and, for the rows read by area, as the map moves). A copy's rhythm is read
// from what its own description says; where nothing says, the note says so.
const REFRESH = {
  adsbmil: "read again every minute while ticked",
  worker: "read afresh as the map moves",
  cerulean: "read afresh as the map moves",
};
function refreshNote(cfg) {
  let t;
  if (LIVE_ROUTES.has(cfg.route) && !NOT_LIVE[cfg.id]) t = REFRESH[cfg.route] || "read afresh each time it is ticked";
  else {
    const said = `${NOT_LIVE[cfg.id] || ""} ${cfg.note || ""} ${cfg.name || ""}`.toLowerCase();
    t = /hourly|every hour/.test(said) ? "copy renewed hourly"
      : /\bdaily\b|each day|every day/.test(said) ? "copy renewed daily"
      : /four weeks|monthly/.test(said) ? "copy renewed every four weeks"
      : /weekly|each week|every week/.test(said) ? "copy renewed weekly"
      : /built once|not updated|made once|retired|is gone|fixed .*release/.test(said) ? "copy made once; not renewed"
      // Where nothing says how often, nothing is said (round 60): "no set
      // rhythm" under dozens of rows told the reader nothing.
      : "";
  }
  return t ? `<span class="refresh">${escapeHtml(t)}</span>` : "";
}
// Rows whose way of reading would count as live, but which draw from a copy
// kept here (the source cannot be read by another site, or its server is gone).
// Every row now carries one mark or the other (22 September, round 3).
